# -------------------- BudgetKu rich dashboard API --------------------
def _member_id_for_session(c, fid):
    name = session.get("member_name") or "Putri"
    row = c.execute("SELECT id FROM members WHERE family_id=? AND name=?", (fid, name)).fetchone()
    if row:
        return row["id"]
    cur = c.execute("INSERT INTO members(family_id,name) VALUES(?,?) RETURNING id", (fid, name)) if using_postgres() else c.execute("INSERT INTO members(family_id,name) VALUES(?,?)", (fid, name))
    mid = cur.fetchone()["id"] if using_postgres() else cur.lastrowid
    c.commit()
    return mid

def _account_row(c, fid, account_id):
    return c.execute("SELECT * FROM accounts WHERE id=? AND family_id=?", (int(account_id), fid)).fetchone()

def _category_id(c, fid, budget_name):
    if not budget_name:
        return None
    row = c.execute("SELECT id FROM categories WHERE family_id=? AND name=?", (fid, budget_name)).fetchone()
    return row["id"] if row else None

def _api_state():
    fid = current_family(); c = db()
    accounts = [dict(x) for x in c.execute("SELECT * FROM accounts WHERE family_id=? ORDER BY id", (fid,)).fetchall()]
    for a in accounts:
        a["type"] = "ewallet" if str(a["type"]).lower().replace("-", "") in ("ewallet", "e wallet") else "bank"
    rows = c.execute("""SELECT t.*, m.name member_name, a.name account_name, cat.name category_name,
        ta.name to_account_name
        FROM transactions t JOIN members m ON m.id=t.member_id JOIN accounts a ON a.id=t.account_id
        LEFT JOIN categories cat ON cat.id=t.category_id
        LEFT JOIN accounts ta ON ta.id=t.to_account_id
        WHERE t.family_id=? ORDER BY t.date DESC,t.id DESC""", (fid,)).fetchall()
    tx=[]
    for r in rows:
        d=dict(r); tx.append({"id":d["id"],"kind":d["kind"],"amount":float(d["amount"]),"date":d["date"],"note":d.get("note") or "Transaksi","account":d["account_name"],"account_id":d["account_id"],"to":d.get("to_account_name"),"to_account_id":d.get("to_account_id"),"budget":d.get("category_name"),"member_name":d.get("member_name")})
    goals=c.execute("SELECT name,target FROM goals WHERE family_id=?",(fid,)).fetchall()
    targets={g["name"]:float(g["target"]) for g in goals}
    c.close()
    return {"accounts":accounts,"transactions":tx,"targets":targets}

@app.route("/api/state")
@login_required
def api_state():
    return jsonify(_api_state())

@app.route("/api/target", methods=["POST"])
@login_required
def api_target():
    data=request.get_json(silent=True) or {}; name=str(data.get("name") or "").strip(); value=float(data.get("value") or 0)
    if not name: return jsonify(error="Nama target tidak valid."),400
    fid=current_family(); c=db(); existing=c.execute("SELECT id FROM goals WHERE family_id=? AND name=?",(fid,name)).fetchone()
    if value<=0:
        if existing: c.execute("DELETE FROM goals WHERE id=? AND family_id=?",(existing["id"],fid))
    elif existing:
        c.execute("UPDATE goals SET target=? WHERE id=? AND family_id=?",(value,existing["id"],fid))
    else:
        c.execute("INSERT INTO goals(family_id,name,target,saved) VALUES(?,?,?,0)",(fid,name,value))
    c.commit(); c.close(); return jsonify(ok=True)

@app.route("/api/opening", methods=["POST"])
@login_required
def api_opening():
    data=request.get_json(silent=True) or {}; balances=data.get("balances") or {}; fid=current_family(); c=db()
    try:
        for aid,val in balances.items():
            a=_account_row(c,fid,aid)
            if a: c.execute("UPDATE accounts SET balance=? WHERE id=? AND family_id=?",(float(val or 0),int(aid),fid))
        c.commit(); return jsonify(ok=True)
    finally: c.close()

@app.route("/api/transaction", methods=["POST"])
@login_required
def api_transaction_create():
    data=request.get_json(silent=True) or {}; fid=current_family(); kind=data.get("kind"); amount=float(data.get("amount") or 0); note=str(data.get("note") or "").strip(); date=data.get("date") or datetime.now().date().isoformat(); aid=data.get("account_id"); budget=str(data.get("budget") or "").strip()
    if kind not in ("income","expense") or amount<=0 or not note or not aid: return jsonify(error="Data transaksi tidak lengkap."),400
    c=db(); a=_account_row(c,fid,aid)
    if not a:return c.close() or (jsonify(error="Rekening tidak ditemukan."),404)
    if kind=="expense" and float(a["balance"])<amount: c.close(); return jsonify(error="Saldo tidak cukup."),400
    mid=_member_id_for_session(c,fid); cid=_category_id(c,fid,budget); delta=amount if kind=="income" else -amount
    c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(delta,aid,fid))
    c.execute("INSERT INTO transactions(family_id,member_id,account_id,category_id,kind,amount,note,date,created_at,to_account_id) VALUES(?,?,?,?,?,?,?,?,?,?)",(fid,mid,aid,cid,kind,amount,note,date,datetime.now().isoformat(),None))
    c.commit(); c.close(); return jsonify(ok=True)

@app.route("/api/transaction/<int:tid>", methods=["PUT","DELETE"])
@login_required
def api_transaction_modify(tid):
    fid=current_family(); c=db(); t=c.execute("SELECT * FROM transactions WHERE id=? AND family_id=?",(tid,fid)).fetchone()
    if not t: c.close(); return jsonify(error="Transaksi tidak ditemukan."),404
    if request.method=="DELETE":
        if t["kind"]=="transfer":
            c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(t["amount"],t["account_id"],fid));
            if t["to_account_id"]: c.execute("UPDATE accounts SET balance=balance-? WHERE id=? AND family_id=?",(t["amount"],t["to_account_id"],fid))
        else:
            delta=-float(t["amount"]) if t["kind"]=="income" else float(t["amount"])
            c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(delta,t["account_id"],fid))
        c.execute("DELETE FROM transactions WHERE id=? AND family_id=?",(tid,fid)); c.commit(); c.close(); return jsonify(ok=True)
    data=request.get_json(silent=True) or {}; kind=data.get("kind"); amount=float(data.get("amount") or 0); note=str(data.get("note") or "").strip(); date=data.get("date") or datetime.now().date().isoformat(); aid=data.get("account_id"); budget=str(data.get("budget") or "").strip()
    if kind not in ("income","expense") or amount<=0 or not note or not aid: c.close(); return jsonify(error="Data transaksi tidak lengkap."),400
    # reverse old effect
    old_delta=-float(t["amount"]) if t["kind"]=="income" else float(t["amount"])
    c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(old_delta,t["account_id"],fid))
    a=_account_row(c,fid,aid)
    if not a: c.rollback(); c.close(); return jsonify(error="Rekening tidak ditemukan."),404
    if kind=="expense" and float(a["balance"])<amount: c.rollback(); c.close(); return jsonify(error="Saldo tidak cukup."),400
    cid=_category_id(c,fid,budget); delta=amount if kind=="income" else -amount
    c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(delta,aid,fid))
    c.execute("UPDATE transactions SET account_id=?,category_id=?,kind=?,amount=?,note=?,date=?,to_account_id=? WHERE id=? AND family_id=?",(aid,cid,kind,amount,note,date,None,tid,fid))
    c.commit(); c.close(); return jsonify(ok=True)

@app.route("/api/transfer", methods=["POST"])
@login_required
def api_transfer_create():
    data=request.get_json(silent=True) or {}; fid=current_family(); amount=float(data.get("amount") or 0); fr=data.get("from_account_id"); to=data.get("to_account_id"); note=str(data.get("note") or "Transfer antar akun"); date=data.get("date") or datetime.now().date().isoformat()
    if amount<=0 or not fr or not to or int(fr)==int(to): return jsonify(error="Transfer tidak valid."),400
    c=db(); a=_account_row(c,fid,fr); b=_account_row(c,fid,to)
    if not a or not b: c.close(); return jsonify(error="Rekening tidak ditemukan."),404
    if float(a["balance"])<amount: c.close(); return jsonify(error="Saldo tidak cukup."),400
    mid=_member_id_for_session(c,fid); c.execute("UPDATE accounts SET balance=balance-? WHERE id=? AND family_id=?",(amount,fr,fid)); c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(amount,to,fid)); c.execute("INSERT INTO transactions(family_id,member_id,account_id,category_id,kind,amount,note,date,created_at,to_account_id) VALUES(?,?,?,?,?,?,?,?,?,?)",(fid,mid,fr,None,"transfer",amount,note,date,datetime.now().isoformat(),to)); c.commit(); c.close(); return jsonify(ok=True)

@app.route("/api/transfer/<int:tid>", methods=["PUT"])
@login_required
def api_transfer_update(tid):
    data=request.get_json(silent=True) or {}; fid=current_family(); amount=float(data.get("amount") or 0); fr=data.get("from_account_id"); to=data.get("to_account_id"); note=str(data.get("note") or "Transfer antar akun"); date=data.get("date") or datetime.now().date().isoformat()
    if amount<=0 or not fr or not to or int(fr)==int(to): return jsonify(error="Transfer tidak valid."),400
    c=db(); t=c.execute("SELECT * FROM transactions WHERE id=? AND family_id=? AND kind='transfer'",(tid,fid)).fetchone()
    if not t: c.close(); return jsonify(error="Transfer tidak ditemukan."),404
    c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(t["amount"],t["account_id"],fid));
    if t["to_account_id"]: c.execute("UPDATE accounts SET balance=balance-? WHERE id=? AND family_id=?",(t["amount"],t["to_account_id"],fid))
    a=_account_row(c,fid,fr); b=_account_row(c,fid,to)
    if not a or not b or float(a["balance"])<amount: c.rollback(); c.close(); return jsonify(error="Rekening tidak valid atau saldo tidak cukup."),400
    c.execute("UPDATE accounts SET balance=balance-? WHERE id=? AND family_id=?",(amount,fr,fid)); c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?",(amount,to,fid)); c.execute("UPDATE transactions SET account_id=?,to_account_id=?,amount=?,note=?,date=? WHERE id=? AND family_id=?",(fr,to,amount,note,date,tid,fid)); c.commit(); c.close(); return jsonify(ok=True)


@app.route("/transaction", methods=["GET", "POST"])
@login_required
def transaction():
    fid = current_family()
    c = db()
    members = c.execute("SELECT * FROM members WHERE family_id=?", (fid,)).fetchall()
    accounts = c.execute("SELECT * FROM accounts WHERE family_id=?", (fid,)).fetchall()
    cats = c.execute("SELECT * FROM categories WHERE family_id=?", (fid,)).fetchall()
    if request.method == "POST":
        member_id = int(request.form["member_id"])
        account_id = int(request.form["account_id"])
        category_id = request.form.get("category_id") or None
        if category_id:
            category_id = int(category_id)
        kind = request.form["kind"]
        amount = float(request.form["amount"])
        date = request.form.get("date") or datetime.now().date().isoformat()
        note = request.form.get("note", "").strip()
        member_ok = c.execute("SELECT id FROM members WHERE id=? AND family_id=?", (member_id, fid)).fetchone()
        account = c.execute("SELECT * FROM accounts WHERE id=? AND family_id=?", (account_id, fid)).fetchone()
        category_ok = (category_id is None or c.execute("SELECT id FROM categories WHERE id=? AND family_id=?", (category_id, fid)).fetchone())
        if not member_ok or not account or not category_ok or kind not in ("income", "expense") or amount <= 0:
            flash("Data transaksi tidak valid.", "error")
        else:
            delta = amount if kind == "income" else -amount
            c.execute("UPDATE accounts SET balance=balance+? WHERE id=? AND family_id=?", (delta, account_id, fid))
            c.execute("""INSERT INTO transactions
                (family_id,member_id,account_id,category_id,kind,amount,note,date,created_at)
                VALUES(?,?,?,?,?,?,?,?,?)""",
                (fid, member_id, account_id, category_id, kind, amount, note, date, datetime.now().isoformat()))
            c.commit()
            c.close()
            return redirect(url_for("dashboard"))
    c.close()
    return render_template("transaction.html", members=members, accounts=accounts,
                           categories=cats, today=datetime.now().date().isoformat())


