# Safe schema migration for existing BudgetKu databases.
def ensure_transfer_column():
    c=db()
    try:
        try:
            c.execute("ALTER TABLE transactions ADD COLUMN to_account_id INTEGER")
            c.commit()
        except Exception:
            c.rollback()
    finally:
        c.close()

# Initialize the schema on startup. In production, DATABASE_URL points to Render Postgres;
# locally, the app keeps using budgetku.db so the project remains easy to test.
init_db()
ensure_transfer_column()
ensure_default_data()

